+// judgeCommand applies the rules to one command word and its arguments. For find it
+// judges each command of an -exec or -execdir action, which ends at a ; or + word.
+func judgeCommand(name string, args []word, xargs bool, c simpleCmd, all []simpleCmd, assigned map[string]bool, command string, owned func(int) bool) (string, bool) {
+	switch name {
+	case "pkill", "killall":
+		return RulePkillKillall, true
+	case "busybox":
+		if len(args) > 0 && args[0].text == "killall" {
+			return RulePkillKillall, true
+		}
+	case "kill":
+		if killsForeign(c, args, xargs, all, assigned, command, owned) {
+			return RuleKillForeignPid, true
+		}
+	case "find":
+		for i := 0; i < len(args); i++ {
+			if args[i].text != "-exec" && args[i].text != "-execdir" {
+				continue
+			}
+			j := i + 1
+			for j < len(args) && args[j].text != ";" && args[j].text != "+" {
+				j++
+			}
+			nested := simpleCmd{args[i+1 : j], c.pipe}
+			n, a, x := commandWord(nested.words)
+			if rule, ok := judgeCommand(n, a, x, nested, all, assigned, command, owned); ok {
+				return rule, true
+			}
+			i = j
+		}
+	}
+	return "", false
+}
